        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                result.data[result.offset + i * result.strides[0] + j * result.strides[1]] = 0.0;
            }
        }
        var i2: usize = 0;
        while (i2 < m) : (i2 += 1) {
            var j2: usize = 0;
            while (j2 < n) : (j2 += 1) {
                var dot_product: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    dot_product += self.data[self.offset + i2 * self.strides[0] + l * self.strides[1]] * other.data[other.offset + l * other.strides[0] + j2 * other.strides[1]];
                }
                result.data[result.offset + i2 * result.strides[0] + j2 * result.strides[1]] = dot_product;
            }
        }
    }

    pub fn transpose(self: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or result.shape.len != 2 or self.shape[0] != result.shape[1] or self.shape[1] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = self.shape[1];
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                result.data[result.offset + j * result.strides[0] + i * result.strides[1]] = self.data[self.offset + i * self.strides[0] + j * self.strides[1]];
            }
        }
    }

    pub fn sum(self: *const Tensor, allocator: Allocator) !Tensor {
        var result = try Tensor.init(allocator, &.{1}, self.dtype);
        var total_sum: f64 = 0.0;
        const total_elements = totalElements(self.shape);
        var i: usize = 0;
        while (i < total_elements) : (i += 1) {
            total_sum += self.data[self.offset + i];
        }
        result.data[result.offset] = total_sum;
        return result;
    }

    pub fn mean(self: *const Tensor, allocator: Allocator) !Tensor {
        var sum_tensor = try self.sum(allocator);
        const total = @as(f64, @floatFromInt(totalElements(self.shape)));
        sum_tensor.data[sum_tensor.offset] /= total;
        return sum_tensor;
    }

    pub fn conv2d(self: *const Tensor, kernel: *const Tensor, padding: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 4 or kernel.shape.len != 4 or self.shape[1] != kernel.shape[1]) {
            return error.InvalidShapeForConv;
        }
        const batch = self.shape[0];
        const in_channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3];
        const out_channels = kernel.shape[0];
        const k_h = kernel.shape[2];
        const k_w = kernel.shape[3];
        const out_h = ((in_h + 2 * padding - k_h) / stride) + 1;
        const out_w = ((in_w + 2 * padding - k_w) / stride) + 1;
        const out_shape = &[_]usize{ batch, out_channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oc: usize = 0;
            while (oc < out_channels) : (oc += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var sum_val: f64 = 0.0;
                        const start_h = @as(isize, @intCast(stride * oh)) - @as(isize, @intCast(padding));
                        const start_w = @as(isize, @intCast(stride * ow)) - @as(isize, @intCast(padding));
                        var kh: usize = 0;
                        while (kh < k_h) : (kh += 1) {
                            const ih = start_h + @as(isize, @intCast(kh));
                            if (ih < 0 or ih >= @as(isize, @intCast(in_h))) continue;
                            var kw: usize = 0;
                            while (kw < k_w) : (kw += 1) {
                                const iw = start_w + @as(isize, @intCast(kw));
                                if (iw < 0 or iw >= @as(isize, @intCast(in_w))) continue;
                                var ic: usize = 0;
                                while (ic < in_channels) : (ic += 1) {
                                    const self_idx = &[_]usize{ b, ic, @as(usize, @intCast(ih)), @as(usize, @intCast(iw)) };
                                    const kernel_idx = &[_]usize{ oc, ic, kh, kw };
                                    sum_val += self.get(self_idx) * kernel.get(kernel_idx);
                                }
                            }
                        }
                        const result_idx = &[_]usize{ b, oc, oh, ow };
                        result.set(result_idx, sum_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn maxpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 4) {
            return error.InvalidShapeForPool;
        }
        const batch = self.shape[0];
        const channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3];
        const out_h = (in_h - kernel_size) / stride + 1;
        const out_w = (in_w - kernel_size) / stride + 1;
        const out_shape = &[_]usize{ batch, channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var c: usize = 0;
            while (c < channels) : (c += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var max_val: f64 = -math.inf(f64);
                        var kh: usize = 0;
                        while (kh < kernel_size) : (kh += 1) {
                            const ih = stride * oh + kh;
                            if (ih >= in_h) break;
                            var kw: usize = 0;
                            while (kw < kernel_size) : (kw += 1) {
                                const iw = stride * ow + kw;
                                if (iw >= in_w) break;
                                const idx = &[_]usize{ b, c, ih, iw };
                                const val = self.get(idx);
                                if (val > max_val) max_val = val;
                            }
                        }
                        const result_idx = &[_]usize{ b, c, oh, ow };
                        result.set(result_idx, max_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn relu(self: *const Tensor, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const val = self.data[self.offset + i];
            result.data[result.offset + i] = if (val > 0.0) val else 0.0;
        }
    }

    pub fn softmax(self: *const Tensor, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var max_val: f64 = -math.inf(f64);
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const val = self.data[self.offset + i];
            if (val > max_val) max_val = val;
        }
        var sum_exp: f64 = 0.0;
        var j: usize = 0;
        while (j < total) : (j += 1) {
            const val = self.data[self.offset + j];
            sum_exp += @exp(val - max_val);
        }
        var k: usize = 0;
        while (k < total) : (k += 1) {
            const val = self.data[self.offset + k];
            result.data[result.offset + k] = @exp(val - max_val) / sum_exp;
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) !void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            const new_grad = try self.allocator.create(Tensor);
            new_grad.* = try Tensor.init(self.allocator, self.shape, self.dtype);
            self.grad = new_grad;
        }
        if (self.grad) |g| {
            if (!mem.eql(usize, g.shape, grad_output.shape)) return error.ShapeMismatch;
            try grad_output.add(g, g);
        }
    }

    pub fn zeroGrad(self: *Tensor) void {
        if (self.grad) |g| {
            @memset(g.data, 0.0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        const total = totalElements(self.shape);
        @memcpy(cloned.data[0..total], self.data[self.offset .. self.offset + total]);
        cloned.offset = 0;
        cloned.requires_grad = self.requires_grad;
        return cloned;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        const magic: u32 = 0x5A494754;
        try writer.writeInt(u32, magic, .little);
        const version: u32 = 1;
        try writer.writeInt(u32, version, .little);
        const ndim = @as(u32, @intCast(self.shape.len));
        try writer.writeInt(u32, ndim, .little);
        for (self.shape) |dim| {
            const dim_u64 = @as(u64, @intCast(dim));
            try writer.writeInt(u64, dim_u64, .little);
        }
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const bytes = mem.asBytes(&self.data[self.offset + i]);
            try writer.writeAll(bytes);
        }
    }

    pub fn load(allocator: Allocator, path: []const u8, dtype: DType) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();
        const magic = try reader.readInt(u32, .little);
        if (magic != 0x5A494754) return error.InvalidMagic;
        const version = try reader.readInt(u32, .little);
        if (version != 1) return error.UnsupportedVersion;
        const ndim_u32 = try reader.readInt(u32, .little);
        const ndim: usize = @intCast(ndim_u32);
        var shape_buf = try allocator.alloc(usize, ndim);
        var i: usize = 0;
        while (i < ndim) : (i += 1) {
            const dim_u64 = try reader.readInt(u64, .little);
            shape_buf[i] = @as(usize, @intCast(dim_u64));
        }
        const total = totalElements(shape_buf);
        const data = try allocator.alloc(f64, total);
        errdefer allocator.free(data);
        var j: usize = 0;
        while (j < total) : (j += 1) {
            const bytes = mem.asBytes(&data[j]);
            const read_count = try reader.readAll(bytes);
            if (read_count != @sizeOf(f64)) {
                allocator.free(data);
                allocator.free(shape_buf);
                return error.IncompleteRead;
            }
        }
        var strides = try allocator.alloc(usize, ndim);
        if (ndim > 0) {
            strides[ndim - 1] = 1;
            var k: usize = ndim;
            while (k > 1) {
                k -= 1;
                strides[k - 1] = strides[k] * shape_buf[k];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_buf,
            .strides = strides,
            .dtype = dtype,
            .offset = 0,
            .is_view = false,
            .requires_grad = false,
            .grad = null,
        };
    }

    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64) !void {
        if (!mem.eql(usize, self.shape, m.shape) or !mem.eql(usize, self.shape, v.shape)) return error.ShapeMismatch;
        const total = totalElements(self.shape);
        var i: usize = 0;
        const t_f = @as(f64, @floatFromInt(t));
        const one: f64 = 1.0;
        while (i < total) : (i += 1) {
            const grad_val = if (self.grad) |g| g.data[g.offset + i] else 0.0;
            const m_old = m.data[m.offset + i];
            const v_old = v.data[v.offset + i];
            const m_new = beta1 * m_old + (one - beta1) * grad_val;
            const v_new = beta2 * v_old + (one - beta2) * grad_val * grad_val;
            m.data[m.offset + i] = m_new;
            v.data[v.offset + i] = v_new;
            const m_hat = m_new / (one - math.pow(f64, beta1, t_f));
            const v_hat = v_new / (one - math.pow(f64, beta2, t_f));
            const update = -lr * m_hat / (@sqrt(v_hat) + eps);
            self.data[self.offset + i] += update;
        }
    }

    pub fn spectral_norm(self: *const Tensor, allocator: Allocator, num_power_iters: usize) !f64 {
        if (self.shape.len != 2) return error.InvalidShape;
        const m = self.shape[0];
        const n = self.shape[1];
        var u = try Tensor.init(allocator, &.{m}, .f64);
        defer u.deinit();
        var v = try Tensor.init(allocator, &.{n}, .f64);
        defer v.deinit();
        var prng = std.rand.DefaultPrng.init(42);
        const rand = prng.random();
        var i: usize = 0;
        while (i < m) : (i += 1) {
            u.data[i] = rand.float(f64) * 2.0 - 1.0;
        }
        var u_norm: f64 = 0.0;
        var i2: usize = 0;
        while (i2 < m) : (i2 += 1) {
            u_norm += u.data[i2] * u.data[i2];
        }
        u_norm = @sqrt(u_norm);
        var i3: usize = 0;
        while (i3 < m) : (i3 += 1) {
            u.data[i3] /= u_norm;
        }
        var iter: usize = 0;
        while (iter < num_power_iters) : (iter += 1) {
            @memset(v.data, 0.0);
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var i4: usize = 0;
                while (i4 < m) : (i4 += 1) {
                    v.data[j] += self.get(&.{ i4, j }) * u.data[i4];
                }
            }
            var v_norm: f64 = 0.0;
            var j2: usize = 0;
            while (j2 < n) : (j2 += 1) {
                v_norm += v.data[j2] * v.data[j2];
            }
            v_norm = @sqrt(v_norm);
            if (v_norm > 1e-12) {
                var j3: usize = 0;
                while (j3 < n) : (j3 += 1) {
                    v.data[j3] /= v_norm;
                }
            }
            @memset(u.data, 0.0);
            var i5: usize = 0;
            while (i5 < m) : (i5 += 1) {
                var j4: usize = 0;
                while (j4 < n) : (j4 += 1) {
                    u.data[i5] += self.get(&.{ i5, j4 }) * v.data[j4];
                }
            }
            u_norm = 0.0;
            var i6: usize = 0;
            while (i6 < m) : (i6 += 1) {
                u_norm += u.data[i6] * u.data[i6];
            }
            u_norm = @sqrt(u_norm);
            if (u_norm > 1e-12) {
                var i7: usize = 0;
                while (i7 < m) : (i7 += 1) {
                    u.data[i7] /= u_norm;
                }
            }
        }
        var sigma: f64 = 0.0;
        var i8: usize = 0;
        while (i8 < m) : (i8 += 1) {
            var j5: usize = 0;
            while (j5 < n) : (j5 += 1) {
                sigma += u.data[i8] * self.get(&.{ i8, j5 }) * v.data[j5];
            }
        }
        return sigma;
    }

    pub fn dropout(self: *const Tensor, p: f64, seed: u64, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        if (p < 0.0 or p >= 1.0) return error.InvalidProbability;
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        const total = totalElements(self.shape);
        const scale = 1.0 / (1.0 - p);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const val = self.data[self.offset + i];
            const drop = rand.float(f64);
            if (drop < p) {
                result.data[result.offset + i] = 0.0;
            } else {
                result.data[result.offset + i] = val * scale;
            }
        }
    }

    pub fn layer_norm(self: *const Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape) or !mem.eql(usize, self.shape, gamma.shape) or !mem.eql(usize, self.shape, beta.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var mean_val: f64 = 0.0;
        var i: usize = 0;
        while (i < total) : (i += 1) {
            mean_val += self.data[self.offset + i];
        }
        mean_val /= @as(f64, @floatFromInt(total));
        var var_sum: f64 = 0.0;
        var j: usize = 0;
        while (j < total) : (j += 1) {
            const val = self.data[self.offset + j];
            const diff = val - mean_val;
            var_sum += diff * diff;
        }
        const variance = var_sum / @as(f64, @floatFromInt(total));
        const std_dev = @sqrt(variance + eps);
        var k: usize = 0;
        while (k < total) : (k += 1) {
            const val = self.data[self.offset + k];
            const normalized = (val - mean_val) / std_dev;
            const gamma_val = gamma.data[gamma.offset + k];
            const beta_val = beta.data[beta.offset + k];
            result.data[result.offset + k] = gamma_val * normalized + beta_val;
        }
    }

    pub fn gelu(self: *const Tensor, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        const sqrt_2_over_pi: f64 = 0.7978845608028654;
        const coeff: f64 = 0.044715;
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const x = self.data[self.offset + i];
            const tanh_arg = sqrt_2_over_pi * (x + coeff * x * x * x);
            const exp_pos = @exp(tanh_arg);
            const exp_neg = @exp(-tanh_arg);
            const tanh_val = (exp_pos - exp_neg) / (exp_pos + exp_neg);
            result.data[result.offset + i] = 0.5 * x * (1.0 + tanh_val);
        }
    }

    pub fn batch_norm(self: *const Tensor, running_mean: *Tensor, running_var: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, training: bool, momentum: f64, result: *Tensor) !void {
        if (!mem.eql(usize, self.shape, result.shape) or self.shape.len < 2) {
            return error.ShapeMismatch;
        }
        const batch_size = self.shape[0];
        const channels = self.shape[1];
        var spatial: usize = 1;
        var d: usize = 2;
        while (d < self.shape.len) : (d += 1) {
            spatial *= self.shape[d];
        }
        var means = try self.allocator.alloc(f64, channels);
        defer self.allocator.free(means);
        @memset(means, 0.0);
        var variances = try self.allocator.alloc(f64, channels);
        defer self.allocator.free(variances);
        @memset(variances, 0.0);
        if (training) {
            var c: usize = 0;
            while (c < channels) : (c += 1) {
                var channel_sum: f64 = 0.0;
                var b: usize = 0;
                while (b < batch_size) : (b += 1) {
                    var s: usize = 0;
                    while (s < spatial) : (s += 1) {
                        const idx = b * (channels * spatial) + c * spatial + s;
                        channel_sum += self.data[self.offset + idx];
                    }
                }
                means[c] = channel_sum / @as(f64, @floatFromInt(batch_size * spatial));
            }
            var c2: usize = 0;
            while (c2 < channels) : (c2 += 1) {
                var var_sum: f64 = 0.0;
                var b2: usize = 0;
                while (b2 < batch_size) : (b2 += 1) {
                    var s2: usize = 0;
                    while (s2 < spatial) : (s2 += 1) {
                        const idx = b2 * (channels * spatial) + c2 * spatial + s2;
                        const val = self.data[self.offset + idx];
                        const diff = val - means[c2];
                        var_sum += diff * diff;
                    }
                }
                variances[c2] = var_sum / @as(f64, @floatFromInt(batch_size * spatial));
            }
            var c3: usize = 0;
            while (c3 < channels) : (c3 += 1) {
                const run_idx = &[_]usize{c3};
                const run_mean_old = running_mean.get(run_idx);
                const run_var_old = running_var.get(run_idx);
                running_mean.set(run_idx, momentum * run_mean_old + (1.0 - momentum) * means[c3]);
                running_var.set(run_idx, momentum * run_var_old + (1.0 - momentum) * variances[c3]);
            }
        } else {
            var c4: usize = 0;
            while (c4 < channels) : (c4 += 1) {
                means[c4] = running_mean.get(&[_]usize{c4});
                variances[c4] = running_var.get(&[_]usize{c4});
            }
        }
        var b3: usize = 0;
        while (b3 < batch_size) : (b3 += 1) {
            var c5: usize = 0;
            while (c5 < channels) : (c5 += 1) {
                var s3: usize = 0;
                while (s3 < spatial) : (s3 += 1) {
                    const idx = b3 * (channels * spatial) + c5 * spatial + s3;
                    const val = self.data[self.offset + idx];
                    const normalized = (val - means[c5]) / @sqrt(variances[c5] + eps);
                    const gamma_val = gamma.get(&[_]usize{c5});
                    const beta_val = beta.get(&[_]usize{c5});
                    result.data[result.offset + idx] = gamma_val * normalized + beta_val;
                }
            }
        }
    }

    pub fn embedding(self: *const Tensor, indices: *const Tensor, allocator: Allocator) !Tensor {
        if (indices.shape.len != 1 or self.shape.len != 2) {
            return error.InvalidShape;
        }
        const vocab_size = self.shape[0];
        const embed_dim = self.shape[1];
        var result = try Tensor.init(allocator, &.{ indices.shape[0], embed_dim }, .f64);
        var i: usize = 0;
        while (i < indices.shape[0]) : (i += 1) {
            const idx_val = @as(usize, @intFromFloat(indices.data[indices.offset + i]));
            if (idx_val >= vocab_size) {
                return error.IndexOutOfBounds;
            }
            var d2: usize = 0;
            while (d2 < embed_dim) : (d2 += 1) {
                const embed_idx = &[_]usize{ idx_val, d2 };
                const val = self.get(embed_idx);
                result.set(&[_]usize{ i, d2 }, val);
            }
        }
        return result;
    }

    pub fn positional_encoding(max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        var pe = try Tensor.init(allocator, &.{ max_len, d_model }, .f64);
        var pos: usize = 0;
        while (pos < max_len) : (pos += 1) {
            const pos_f = @as(f64, @floatFromInt(pos));
            var i: usize = 0;
            while (i < d_model) : (i += 1) {
                const i_f = @as(f64, @floatFromInt(i));
                const exponent = (2.0 * @floor(i_f / 2.0)) / @as(f64, @floatFromInt(d_model));
                const div_term = math.pow(f64, 10000.0, exponent);
                const angle = pos_f / div_term;
                if (i % 2 == 0) {
                    pe.set(&[_]usize{ pos, i }, @sin(angle));
                } else {
                    pe.set(&[_]usize{ pos, i }, @cos(angle));
                }
            }
        }
        return pe;
    }

    pub fn sparse_matmul(self: *const Tensor, other: *const Tensor, sparsity: f64, seed: u64, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0]) {
            return error.ShapeMismatch;
        }
        var dense_result = try Tensor.init(allocator, &.{ self.shape[0], other.shape[1] }, .f64);
        defer dense_result.deinit();
        try self.matmul(other, &dense_result);
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        var sparse_result = try Tensor.init(allocator, dense_result.shape, .f64);
        const total = totalElements(dense_result.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const keep = rand.float(f64) > sparsity;
            sparse_result.data[sparse_result.offset + i] = if (keep) dense_result.data[dense_result.offset + i] else 0.0;
        }
        return sparse_result;
    }
};

pub fn fft(input: []Complex, output: []Complex, allocator: Allocator) !void {
    const n = input.len;
    if (n != output.len) return error.LengthMismatch;
    if (n <= 1) {
        @memcpy(output, input);
        return;
    }
    if ((n & (n - 1)) != 0) return error.NotPowerOfTwo;
    const half = n / 2;
    var even = try allocator.alloc(Complex, half);
    defer allocator.free(even);
    var odd = try allocator.alloc(Complex, half);
    defer allocator.free(odd);
    var i: usize = 0;
    while (i < half) : (i += 1) {
        even[i] = input[2 * i];
        odd[i] = input[2 * i + 1];
    }
    const even_fft = try allocator.alloc(Complex, half);
    defer allocator.free(even_fft);
    const odd_fft = try allocator.alloc(Complex, half);
    defer allocator.free(odd_fft);
    try fft(even, even_fft, allocator);
    try fft(odd, odd_fft, allocator);
    var k: usize = 0;
    while (k < half) : (k += 1) {
        const angle = -2.0 * math.pi * @as(f64, @floatFromInt(k)) / @as(f64, @floatFromInt(n));
        const twiddle = Complex.init(@cos(angle), @sin(angle));
        const t = twiddle.mul(odd_fft[k]);
        output[k] = even_fft[k].add(t);
        output[k + half] = even_fft[k].sub(t);
    }
}

pub fn ifft(input: []Complex, output: []Complex, allocator: Allocator) !void {
    const n = input.len;
    if (n != output.len) return error.LengthMismatch;
    var conjugated = try allocator.alloc(Complex, n);
    defer allocator.free(conjugated);
    var i: usize = 0;
    while (i < n) : (i += 1) {
        conjugated[i] = Complex.init(input[i].real, -input[i].imag);
    }
    const fft_result = try allocator.alloc(Complex, n);
    defer allocator.free(fft_result);
    try fft(conjugated, fft_result, allocator);
    const n_f = @as(f64, @floatFromInt(n));
    var j: usize = 0;
    while (j < n) : (j += 1) {
        output[j] = Complex.init(fft_result[j].real / n_f, -fft_result[j].imag / n_f);
    }
}

pub fn hadamard_transform(input: []f64, output: []f64) !void {
    const n = input.len;
    if (n != output.len) return error.LengthMismatch;
    if ((n & (n - 1)) != 0) return error.NotPowerOfTwo;
    @memcpy(output, input);
    var h: usize = 1;
    while (h < n) : (h *= 2) {
        var i: usize = 0;
        while (i < n) : (i += h * 2) {
            var j: usize = 0;
            while (j < h) : (j += 1) {
                const idx1 = i + j;
                const idx2 = i + j + h;
                const a = output[idx1];
                const b = output[idx2];
                output[idx1] = a + b;
                output[idx2] = a - b;
            }
        }
    }
    const norm = @sqrt(@as(f64, @floatFromInt(n)));
    var k: usize = 0;
    while (k < n) : (k += 1) {
        output[k] /= norm;
    }
}

pub fn bspline_basis(t: f64, i: usize, k: usize, knots: []const f64, allocator: Allocator) !f64 {
    _ = allocator;
    if (k == 0) {
        if (i >= knots.len - 1) return 0.0;
        return if (t >= knots[i] and t < knots[i + 1]) 1.0 else 0.0;
    }
    var left: f64 = 0.0;
    var right: f64 = 0.0;
    if (i + k < knots.len) {
        const denom_left = knots[i + k] - knots[i];
        if (@abs(denom_left) > 1e-10) {
            const basis_left = try bspline_basis(t, i, k - 1, knots, allocator);
            left = (t - knots[i]) / denom_left * basis_left;
        }
    }
    if (i + k + 1 < knots.len and i + 1 < knots.len) {
        const denom_right = knots[i + k + 1] - knots[i + 1];
        if (@abs(denom_right) > 1e-10) {
            const basis_right = try bspline_basis(t, i + 1, k - 1, knots, allocator);
            right = (knots[i + k + 1] - t) / denom_right * basis_right;
        }
    }
    return left + right;
}

pub fn lorenz_attractor(x0: f64, y0: f64, z0: f64, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !Tensor {
    var trajectory = try Tensor.init(allocator, &.{ steps, 3 }, .f64);
    var x = x0;
    var y = y0;
    var z = z0;
    var step: usize = 0;
    while (step < steps) : (step += 1) {
        trajectory.set(&.{ step, 0 }, x);
        trajectory.set(&.{ step, 1 }, y);
        trajectory.set(&.{ step, 2 }, z);
        const dx = sigma * (y - x);
        const dy = x * (rho - z) - y;
        const dz = x * y - beta * z;
        x += dx * dt;
        y += dy * dt;
        z += dz * dt;
    }
    return trajectory;
}

pub fn s4d_ssm(input: *const Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, D: *const Tensor, dt: f64, allocator: Allocator) !Tensor {
    _ = dt;
    if (input.shape.len != 2) return error.InvalidShape;
    const seq_len = input.shape[0];
    const input_dim = input.shape[1];
    if (A.shape.len != 1 or B.shape.len != 1 or C.shape.len != 1 or D.shape.len != 2) {
        return error.InvalidShape;
    }
    const state_dim = A.shape[0];
    if (B.shape[0] != state_dim or C.shape[0] != state_dim or D.shape[0] != input_dim or D.shape[1] != input_dim) {
        return error.ShapeMismatch;
    }
    var output = try Tensor.init(allocator, input.shape, .f64);
    var state = try Tensor.init(allocator, &.{state_dim}, .f64);
    defer state.deinit();
    var t: usize = 0;
    while (t < seq_len) : (t += 1) {
        var new_state = try Tensor.init(allocator, &.{state_dim}, .f64);
        var s: usize = 0;
        while (s < state_dim) : (s += 1) {
            const a_val = A.data[A.offset + s];
            const b_val = B.data[B.offset + s];
            var input_contrib: f64 = 0.0;
            var d: usize = 0;
            while (d < input_dim) : (d += 1) {
                input_contrib += input.get(&.{ t, d }) * b_val;
            }
            const disc_a = @exp(a_val * dt);
            const old_state_val = state.data[state.offset + s];
            const incr = if (@abs(a_val) < 1e-12) dt * input_contrib else (1.0 - disc_a) / a_val * input_contrib;
            new_state.data[new_state.offset + s] = disc_a * old_state_val + incr;
        }
        state.deinit();
        state = new_state;
        var d2: usize = 0;
        while (d2 < input_dim) : (d2 += 1) {
            var out_val: f64 = 0.0;
            var s2: usize = 0;
            while (s2 < state_dim) : (s2 += 1) {
                const c_val = C.data[C.offset + s2];
                out_val += c_val * state.data[state.offset + s2];
            }
            const d_val = D.get(&.{ d2, d2 });
            out_val += d_val * input.get(&.{ t, d2 });
            output.set(&.{ t, d2 }, out_val);
        }
    }
    return output;
}

pub fn hyena_conv(input: *const Tensor, short_filter: *const Tensor, long_filter: *const Tensor, allocator: Allocator) !Tensor {
    if (input.shape.len != 2 or short_filter.shape.len != 1 or long_filter.shape.len != 1) {
        return error.InvalidShape;
    }
    const seq_len = input.shape[0];
    const channels = input.shape[1];
    const short_len = short_filter.shape[0];
    const long_len = long_filter.shape[0];
    var short_conv = try Tensor.init(allocator, input.shape, .f64);
    defer short_conv.deinit();
    var t: usize = 0;
    while (t < seq_len) : (t += 1) {
        var c: usize = 0;
        while (c < channels) : (c += 1) {
            var conv_sum: f64 = 0.0;
            var k: usize = 0;
            while (k < short_len) : (k += 1) {
                if (t >= k) {
                    const idx = t - k;
                    conv_sum += input.get(&.{ idx, c }) * short_filter.data[short_filter.offset + k];
                }
            }
            short_conv.set(&.{ t, c }, conv_sum);
        }
    }
    var output = try Tensor.init(allocator, input.shape, .f64);
    var t2: usize = 0;
    while (t2 < seq_len) : (t2 += 1) {
        var c2: usize = 0;
        while (c2 < channels) : (c2 += 1) {
            var conv_sum: f64 = 0.0;
            var k2: usize = 0;
            while (k2 < long_len) : (k2 += 1) {
                if (t2 >= k2) {
                    const idx = t2 - k2;
                    conv_sum += short_conv.get(&.{ idx, c2 }) * long_filter.data[long_filter.offset + k2];
                }
            }
            output.set(&.{ t2, c2 }, conv_sum);
        }
    }
    return output;
}

pub fn mamba2_ssm(input: *const Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, delta: *const Tensor, allocator: Allocator) !Tensor {
    if (input.shape.len != 2 or delta.shape.len != 2) return error.InvalidShape;
    const seq_len = input.shape[0];
    const input_dim = input.shape[1];
    if (delta.shape[0] != seq_len or delta.shape[1] != input_dim) {
        return error.ShapeMismatch;
    }
    if (A.shape.len != 1 or B.shape.len != 2 or C.shape.len != 2) {
        return error.InvalidShape;
    }
    const state_dim = A.shape[0];
    if (B.shape[0] != state_dim or B.shape[1] != input_dim or C.shape[0] != state_dim or C.shape[1] != input_dim) return error.ShapeMismatch;
    var output = try Tensor.init(allocator, input.shape, .f64);
    var state = try Tensor.init(allocator, &.{ state_dim, input_dim }, .f64);
    defer state.deinit();
    var t: usize = 0;
    while (t < seq_len) : (t += 1) {
        var d: usize = 0;
        while (d < input_dim) : (d += 1) {
            const dt = delta.get(&.{ t, d });
            const x_t = input.get(&.{ t, d });
            var s: usize = 0;
            while (s < state_dim) : (s += 1) {
                const a_val = A.data[A.offset + s];
                const b_val = B.get(&.{ s, d });
                const disc_a = @exp(a_val * dt);
                const old_state = state.get(&.{ s, d });
                const new_state = disc_a * old_state + b_val * x_t * dt;
                state.set(&.{ s, d }, new_state);
            }
            var out_val: f64 = 0.0;
            var s2: usize = 0;
            while (s2 < state_dim) : (s2 += 1) {
                const c_val = C.get(&.{ s2, d });
                out_val += c_val * state.get(&.{ s2, d });
            }
            output.set(&.{ t, d }, out_val);
        }
    }
    return output;
}

pub fn retnet_retention(input: *const Tensor, gamma: f64, allocator: Allocator) !Tensor {
    if (input.shape.len != 2) return error.InvalidShape;
    const seq_len = input.shape[0];
    const dim = input.shape[1];
    var output = try Tensor.init(allocator, input.shape, .f64);
    var retention_state = try Tensor.init(allocator, &.{dim}, .f64);
    defer retention_state.deinit();
    var t: usize = 0;
    while (t < seq_len) : (t += 1) {
        var d: usize = 0;
        while (d < dim) : (d += 1) {
            const x_t = input.get(&.{ t, d });
            const prev_state = retention_state.data[retention_state.offset + d];
            const new_state = gamma * prev_state + x_t;
            retention_state.data[retention_state.offset + d] = new_state;
            var output_val: f64 = 0.0;
            var k: usize = 0;
            while (k <= t) : (k += 1) {
                const decay = math.pow(f64, gamma, @as(f64, @floatFromInt(t - k)));
                output_val += decay * input.get(&.{ k, d });
            }
            output.set(&.{ t, d }, output_val);
        }
    }
    return output;
}

pub fn astro_align_transform(ra_deg: f64, dec_deg: f64, rotation: f64, scale: f64) ![2]f64 {
    const ra_rad = ra_deg * math.pi / 180.0;
    const dec_rad = dec_deg * math.pi / 180.0;
    const x_proj = @cos(dec_rad) * @cos(ra_rad);
    const y_proj = @cos(dec_rad) * @sin(ra_rad);
    const z_proj = @sin(dec_rad);
    const rot_rad = rotation * math.pi / 180.0;
    const cos_rot = @cos(rot_rad);
    const sin_rot = @sin(rot_rad);
    const x_rot = x_proj * cos_rot - y_proj * sin_rot;
    const y_rot = x_proj * sin_rot + y_proj * cos_rot;
    const x_scaled = x_rot * scale;
    const y_scaled = y_rot * scale;
    const r = @sqrt(x_scaled * x_scaled + y_scaled * y_scaled + z_proj * z_proj);
    if (r < 1e-10) return error.DegenerateCoordinates;
    return [2]f64{ x_scaled / r, y_scaled / r };
}

pub fn zo_optimization(loss_fn: fn ([]const f64) f64, x0: []const f64, mu: f64, num_samples: usize, lr: f64, iterations: usize, seed: u64, allocator: Allocator) ![]f64 {
    var x = try allocator.alloc(f64, x0.len);
    @memcpy(x, x0);
    var prng = std.rand.DefaultPrng.init(seed);
    const rand = prng.random();
    var directions = try allocator.alloc(f64, x0.len * num_samples);
    defer allocator.free(directions);
    var iter: usize = 0;
    while (iter < iterations) : (iter += 1) {
        const f_x = loss_fn(x);
        var s: usize = 0;
        while (s < num_samples) : (s += 1) {
            var norm: f64 = 0.0;
            var d: usize = 0;
            while (d < x0.len) : (d += 1) {
                const u1 = @max(rand.float(f64), 1e-12);
                const u2 = rand.float(f64);
                const r = @sqrt(-2.0 * @log(u1));
                const theta = 2.0 * math.pi * u2;
                const z = if ((d & 1) == 0) r * @cos(theta) else r * @sin(theta);
                directions[s * x0.len + d] = z;
                norm += z * z;
            }
            norm = @sqrt(norm);
            var d2: usize = 0;
            while (d2 < x0.len) : (d2 += 1) {
                directions[s * x0.len + d2] /= norm;
            }
        }
        var grad = try allocator.alloc(f64, x0.len);
        defer allocator.free(grad);
        @memset(grad, 0.0);
        var s2: usize = 0;
        while (s2 < num_samples) : (s2 += 1) {
            var x_perturbed = try allocator.alloc(f64, x0.len);
            defer allocator.free(x_perturbed);
            var d3: usize = 0;
            while (d3 < x0.len) : (d3 += 1) {
                x_perturbed[d3] = x[d3] + mu * directions[s2 * x0.len + d3];
            }
            const f_perturbed = loss_fn(x_perturbed);
            const diff = (f_perturbed - f_x) / mu;
            var d4: usize = 0;
            while (d4 < x0.len) : (d4 += 1) {
                grad[d4] += diff * directions[s2 * x0.len + d4];
            }
        }
        const n_samples = @as(f64, @floatFromInt(num_samples));
        var d5: usize = 0;
        while (d5 < x0.len) : (d5 += 1) {
            grad[d5] /= n_samples;
            x[d5] -= lr * grad[d5];
        }
    }
    return x;
}

pub fn secure_message_parse(message: []const u8, key: []const u8, allocator: Allocator) ![]u8 {
    if (message.len < 16) return error.MessageTooShort;
    if (key.len < 32) return error.KeyTooShort;
    const header_magic = message[0..4];
    if (!mem.eql(u8, header_magic, &[_]u8{ 0x53, 0x4D, 0x53, 0x47 })) {
        return error.InvalidMagic;
    }
    const version = message[4];
    if (version != 1) return error.UnsupportedVersion;
    const msg_len_bytes = message[5..9];
    var msg_len: u32 = 0;
    var i: usize = 0;
    while (i < 4) : (i += 1) {
        msg_len |= @as(u32, msg_len_bytes[i]) << @intCast(i * 8);
    }
    const checksum_bytes = message[9..13];
    var expected_checksum: u32 = 0;
    var j: usize = 0;
    while (j < 4) : (j += 1) {
        expected_checksum |= @as(u32, checksum_bytes[j]) << @intCast(j * 8);
    }
    if (13 + msg_len > message.len) return error.TruncatedMessage;
    const encrypted_data = message[13 .. 13 + msg_len];
    var decrypted = try allocator.alloc(u8, msg_len);
    var k: usize = 0;
    while (k < msg_len) : (k += 1) {
        const key_byte = key[k % key.len];
        decrypted[k] = encrypted_data[k] ^ key_byte;
    }
    var computed_checksum: u32 = 0;
    for (decrypted) |byte| {
        computed_checksum = computed_checksum +% byte;
    }
    if (computed_checksum != expected_checksum) {
        allocator.free(decrypted);
        return error.ChecksumMismatch;
    }
    return decrypted;
}

pub fn sigmoid(input: *const Tensor, output: *Tensor) !void {
    if (!mem.eql(usize, input.shape, output.shape)) {
        return error.ShapeMismatch;
    }
    const total = totalElements(input.shape);
    var i: usize = 0;
    while (i < total) : (i += 1) {
        const x = input.data[input.offset + i];
        output.data[output.offset + i] = 1.0 / (1.0 + @exp(-x));
    }
}
